with f as materialized (select public.customer_gacha_draw('race-cust-token-0123456789abcdef0123456789')::text as r, clock_timestamp() as t) select f.r || ' ｜処理 ' || to_char(f.t at time zone 'Asia/Tokyo', 'HH24:MI:SS.MS') || ' 鍵を離す ' || to_char(clock_timestamp() at time zone 'Asia/Tokyo', 'HH24:MI:SS.MS') as r from f cross join lateral (select pg_sleep(20) where f.r is not null) s;
